1	<?php
2	
3	namespace App\Services\Square;
4	
5	use App\Models\Core\Professional\Professional;
6	use App\Models\Core\Professional\ProfessionalIntegration;
7	use App\Models\Core\Professional\Service;
8	use App\Models\Core\Professional\ServiceCategory;
9	use Carbon\CarbonImmutable;
10	use Illuminate\Support\Facades\DB;
11	use Illuminate\Support\Facades\Log;
12	
13	// V2: Bidirectional service sync between Square and Side St. Booking integration — not V2 commerce.
14	class SquareServiceSyncService
15	{
16	    public function __construct(
17	        private readonly SquareApiClient $squareApiClient
18	    ) {}
19	
20	    /**
21	     * Pull services from Square and upsert into Commet.
22	     *
23	     * @return array{synced:int, deleted:int, latest_time:string|null}
24	     */
25	    public function syncFromSquare(Professional $professional, bool $fullSync = false, ?string $beginTimeOverride = null): array
26	    {
27	        $integration = $professional->integrationForProvider(ProfessionalIntegration::PROVIDER_SQUARE);
28	        if (! $integration || empty($integration->access_token) || empty($integration->external_account_id)) {
29	            return ['synced' => 0, 'deleted' => 0, 'latest_time' => null];
30	        }
31	
32	        $beginTime = $beginTimeOverride;
33	        if ($beginTime === null && ! $fullSync && $integration->catalog_latest_time) {
34	            $beginTime = CarbonImmutable::parse($integration->catalog_latest_time)->toIso8601String();
35	        }
36	
37	        try {
38	            $fetched = $this->squareApiClient->fetchAppointmentServiceVariations($professional, $beginTime);
39	            $stats = $this->applySquareSnapshot($professional, $fetched['services'] ?? [], $fullSync);
40	
41	            $integration->catalog_latest_time = isset($fetched['latest_time']) && is_string($fetched['latest_time'])
42	                ? CarbonImmutable::parse($fetched['latest_time'])
43	                : now();
44	            $integration->last_catalog_sync_at = now();
45	            $integration->last_catalog_sync_error = null;
46	            $integration->save();
47	
48	            return [
49	                'synced' => $stats['synced'],
50	                'deleted' => $stats['deleted'],
51	                'latest_time' => $fetched['latest_time'] ?? null,
52	            ];
53	        } catch (\Throwable $e) {
54	            $integration->last_catalog_sync_error = mb_substr($e->getMessage(), 0, 2000);
55	            $integration->last_catalog_sync_at = now();
56	            $integration->save();
57	            throw $e;
58	        }
59	    }
60	
61	    /**
62	     * Push one Commet service mutation to Square.
63	     */
64	    public function pushServiceToSquare(Service $service, string $action = 'upsert'): void
65	    {
66	        $professional = Professional::query()->find($service->professional_id);
67	        if (! $professional) {
68	            return;
69	        }
70	        $integration = $professional->integrationForProvider(ProfessionalIntegration::PROVIDER_SQUARE);
71	        if (! $integration || empty($integration->access_token) || empty($integration->external_account_id)) {
72	            return;
73	        }
74	
75	        // Respect "smart sync" toggle when present.
76	        $smartSyncEnabled = (bool) data_get($professional->site?->settings, 'services_auto_sync_enabled', false);
77	        if (! $smartSyncEnabled) {
78	            return;
79	        }
80	
81	        try {
82	            if ($action === 'delete' || $service->trashed()) {
83	                $itemId = trim((string) ($service->square_catalog_object_id ?? ''));
84	                if ($itemId !== '') {
85	                    try {
86	                        $this->squareApiClient->deleteCatalogObject($professional, $itemId);
87	                    } catch (SquareApiException $e) {
88	                        if ($e->status !== 404) {
89	                            throw $e;
90	                        }
91	                    }
92	                }
93	
94	                Service::withoutEvents(function () use ($service): void {
95	                    Service::query()
96	                        ->withTrashed()
97	                        ->where('id', $service->id)
98	                        ->update([
99	                            'square_last_synced_at' => now(),
100	                            'square_sync_error' => null,
101	                        ]);
102	                });
103	
104	                return;
105	            }
106	
107	            $itemId = $this->existingOrTempId($service->square_catalog_object_id, 'item', $service->id);
108	            $variationId = $this->existingOrTempId($service->square_variation_id, 'var', $service->id);
109	            $itemVersion = $service->square_catalog_version;
110	
111	            $catalogObject = [
112	                'type' => 'ITEM',
113	                'id' => $itemId,
114	                'item_data' => [
115	                    'name' => $service->title,
116	                    'description' => $service->description ?: null,
117	                    'product_type' => 'APPOINTMENTS_SERVICE',
118	                    'variations' => [[
119	                        'type' => 'ITEM_VARIATION',
120	                        'id' => $variationId,
121	                        'item_variation_data' => [
122	                            'item_id' => $itemId,
123	                            'name' => 'Default',
124	                            'pricing_type' => 'FIXED_PRICING',
125	                            'price_money' => [
126	                                'amount' => max(0, (int) ($service->price_cents ?? 0)),
127	                                'currency' => strtoupper((string) ($service->currency_code ?: 'AUD')),
128	                            ],
129	                            'service_duration' => $service->duration_minutes
130	                                ? ((int) $service->duration_minutes * 60 * 1000)
131	                                : null,
132	                            'available_for_booking' => (bool) $service->is_active,
133	                        ],
134	                    ]],
135	                ],
136	            ];
137	
138	            if ($itemVersion !== null && ! str_starts_with($itemId, '#')) {
139	                $catalogObject['version'] = (int) $itemVersion;
140	            }
141	
142	            try {
143	                $upserted = $this->squareApiClient->upsertCatalogObject($professional, $catalogObject);
144	            } catch (SquareApiException $e) {
145	                // If Square has a newer version than we have, retry once with latest version.
146	                if ($e->status !== 400 && $e->status !== 409) {
147	                    throw $e;
148	                }
149	                if (str_starts_with($itemId, '#')) {
150	                    throw $e;
151	                }
152	
153	                $latest = $this->squareApiClient->retrieveCatalogObject($professional, $itemId);
154	                if (! $latest) {
155	                    throw $e;
156	                }
157	
158	                $catalogObject['version'] = isset($latest['version']) ? (int) $latest['version'] : $catalogObject['version'] ?? null;
159	                $latestVariationId = data_get($latest, 'item_data.variations.0.id');
160	                if (is_string($latestVariationId) && $latestVariationId !== '') {
161	                    $catalogObject['item_data']['variations'][0]['id'] = $latestVariationId;
162	                    $catalogObject['item_data']['variations'][0]['item_variation_data']['item_id'] = $itemId;
163	                }
164	
165	                $upserted = $this->squareApiClient->upsertCatalogObject($professional, $catalogObject);
166	            }
167	
168	            $resolvedItemId = (string) ($upserted['id'] ?? $service->square_catalog_object_id ?? '');
169	            $resolvedVariationId = (string) (data_get($upserted, 'item_data.variations.0.id') ?? $service->square_variation_id ?? '');
170	            $resolvedVersion = isset($upserted['version']) ? (int) $upserted['version'] : $service->square_catalog_version;
171	
172	            Service::withoutEvents(function () use ($service, $resolvedItemId, $resolvedVariationId, $resolvedVersion): void {
173	                Service::query()
174	                    ->withTrashed()
175	                    ->where('id', $service->id)
176	                    ->update([
177	                        'square_catalog_object_id' => $resolvedItemId !== '' ? $resolvedItemId : null,
178	                        'square_variation_id' => $resolvedVariationId !== '' ? $resolvedVariationId : null,
179	                        'square_catalog_version' => $resolvedVersion,
180	                        'square_last_synced_at' => now(),
181	                        'square_sync_error' => null,
182	                    ]);
183	            });
184	        } catch (\Throwable $e) {
185	            Service::withoutEvents(function () use ($service, $e): void {
186	                Service::query()
187	                    ->withTrashed()
188	                    ->where('id', $service->id)
189	                    ->update([
190	                        'square_sync_error' => mb_substr($e->getMessage(), 0, 2000),
191	                    ]);
192	            });
193	
194	            Log::warning('Square push from Commet failed', [
195	                'service_id' => $service->id,
196	                'professional_id' => $service->professional_id,
197	                'message' => $e->getMessage(),
198	            ]);
199	
200	            throw $e;
201	        }
202	    }
203	
204	    /**
205	     * @param  array<int, array<string, mixed>>  $squareRows
206	     * @return array{synced:int, deleted:int}
207	     */
208	    private function applySquareSnapshot(Professional $professional, array $squareRows, bool $fullSync): array
209	    {
210	        $syncedVariationIds = [];
211	        $syncedCount = 0;
212	        $deletedCount = 0;
213	
214	        DB::transaction(function () use (
215	            $professional,
216	            $squareRows,
217	            &$syncedVariationIds,
218	            &$syncedCount,
219	            &$deletedCount
220	        ): void {
221	            $existingCategories = ServiceCategory::query()
222	                ->withTrashed()
223	                ->where('professional_id', $professional->id)
224	                ->orderBy('sort_order')
225	                ->orderBy('created_at')
226	                ->get();
227	
228	            $activeCategoryIdByKey = [];
229	            $trashedCategoryByKey = [];
230	            $nextCategorySort = ((int) ($existingCategories->max('sort_order') ?? -1)) + 1;
231	            foreach ($existingCategories as $category) {
232	                $key = $this->categoryKey((string) $category->title);
233	                if ($key === '') {
234	                    continue;
235	                }
236	
237	                if ($category->trashed()) {
238	                    $trashedCategoryByKey[$key] = $category;
239	
240	                    continue;
241	                }
242	
243	                $activeCategoryIdByKey[$key] = $category->id;
244	            }
245	
246	            $nextGlobalSortOrder = (int) (Service::query()
247	                ->where('professional_id', $professional->id)
248	                ->whereNull('deleted_at')
249	                ->max('sort_order') ?? -1) + 1;
250	
251	            Service::withoutEvents(function () use (
252	                $professional,
253	                $squareRows,
254	                &$syncedVariationIds,
255	                &$nextGlobalSortOrder,
256	                &$activeCategoryIdByKey,
257	                &$trashedCategoryByKey,
258	                &$nextCategorySort,
259	                &$syncedCount,
260	                &$deletedCount
261	            ): void {
262	                foreach ($squareRows as $row) {
263	                    if (! is_array($row)) {
264	                        continue;
265	                    }
266	
267	                    $itemId = trim((string) ($row['item_id'] ?? ''));
268	                    if ($itemId === '') {
269	                        continue;
270	                    }
271	
272	                    $isDeleted = (bool) ($row['deleted'] ?? false);
273	                    if ($isDeleted) {
274	                        $variationId = trim((string) ($row['variation_id'] ?? ''));
275	                        $toDelete = Service::query()->where('professional_id', $professional->id);
276	                        if ($variationId !== '') {
277	                            $toDelete->where('square_variation_id', $variationId);
278	                        } else {
279	                            $toDelete->where('square_catalog_object_id', $itemId);
280	                        }
281	                        $toDelete = $toDelete
282	                            ->whereNull('deleted_at')
283	                            ->get();
284	
285	                        foreach ($toDelete as $service) {
286	                            $service->is_active = false;
287	                            $service->save();
288	                            $service->delete();
289	                            $deletedCount++;
290	                        }
291	
292	                        continue;
293	                    }
294	
295	                    $variationId = trim((string) ($row['variation_id'] ?? ''));
296	                    if ($variationId === '') {
297	                        continue;
298	                    }
299	
300	                    $syncedVariationIds[] = $variationId;
301	
302	                    $title = trim((string) ($row['item_name'] ?? 'Service'));
303	                    $variationName = trim((string) ($row['variation_name'] ?? ''));
304	                    $isGenericVariationName = in_array(mb_strtolower($variationName), ['regular', 'default'], true);
305	                    if ($variationName !== '' && ! $isGenericVariationName && strcasecmp($variationName, $title) !== 0) {
306	                        $title = sprintf('%s - %s', $title, $variationName);
307	                    }
308	                    $categoryId = $this->resolveCategoryIdFromSquareRow(
309	                        $professional->id,
310	                        $row,
311	                        $activeCategoryIdByKey,
312	                        $trashedCategoryByKey,
313	                        $nextCategorySort
314	                    );
315	
316	                    $service = Service::query()
317	                        ->withTrashed()
318	                        ->where('professional_id', $professional->id)
319	                        ->where('square_variation_id', $variationId)
320	                        ->first();
321	
322	                    $priceCents = isset($row['price_cents']) ? (int) $row['price_cents'] : null;
323	                    $currencyCode = strtoupper((string) ($row['currency_code'] ?? ''));
324	                    $durationMinutes = isset($row['duration_minutes']) ? (int) $row['duration_minutes'] : null;
325	                    $availableForBooking = (bool) ($row['available_for_booking'] ?? false);
326	                    $itemVersion = isset($row['item_version']) ? (int) $row['item_version'] : null;
327	
328	                    if (! $service) {
329	                        $service = Service::query()->create([
330	                            'professional_id' => $professional->id,
331	                            'category_id' => $categoryId,
332	                            'title' => $title,
333	                            'description' => isset($row['item_description']) ? (string) $row['item_description'] : null,
334	                            'price_cents' => $priceCents ?? 0,
335	                            'currency_code' => $currencyCode !== '' ? $currencyCode : 'AUD',
336	                            'duration_minutes' => $durationMinutes,
337	                            'is_active' => $availableForBooking,
338	                            'sort_order' => $nextGlobalSortOrder++,
339	                            'square_catalog_object_id' => $itemId,
340	                            'square_variation_id' => $variationId,
341	                            'square_catalog_version' => $itemVersion,
342	                            'square_last_synced_at' => now(),
343	                            'square_sync_error' => null,
344	                        ]);
345	                    } else {
346	                        $previousCategoryId = $service->category_id;
347	                        $wasTrashed = $service->trashed();
348	                        $service->fill([
349	                            'category_id' => $categoryId,
350	                            'title' => $title,
351	                            'description' => isset($row['item_description']) ? (string) $row['item_description'] : null,
352	                            'price_cents' => $priceCents ?? $service->price_cents ?? 0,
353	                            'currency_code' => $currencyCode !== '' ? $currencyCode : ($service->currency_code ?: 'AUD'),
354	                            'duration_minutes' => $durationMinutes,
355	                            'is_active' => $availableForBooking,
356	                            'square_catalog_object_id' => $itemId,
357	                            'square_variation_id' => $variationId,
358	                            'square_catalog_version' => $itemVersion ?? $service->square_catalog_version,
359	                            'square_last_synced_at' => now(),
360	                            'square_sync_error' => null,
361	                        ]);
362	                        if ($previousCategoryId !== $categoryId || $wasTrashed) {
363	                            $service->sort_order = $nextGlobalSortOrder++;
364	                        }
365	                        $service->save();
366	                    }
367	
368	                    if ($service->trashed()) {
369	                        $service->restore();
370	                    }
371	
372	                    $syncedCount++;
373	                }
374	            });
375	        });
376	
377	        if ($fullSync) {
378	            Service::withoutEvents(function () use ($professional, $syncedVariationIds, &$deletedCount): void {
379	                $missingQuery = Service::query()
380	                    ->where('professional_id', $professional->id)
381	                    ->whereNotNull('square_variation_id')
382	                    ->whereNull('deleted_at');
383	
384	                if (! empty($syncedVariationIds)) {
385	                    $missingQuery->whereNotIn('square_variation_id', array_values(array_unique($syncedVariationIds)));
386	                }
387	
388	                $missing = $missingQuery->get();
389	
390	                foreach ($missing as $service) {
391	                    $service->is_active = false;
392	                    $service->save();
393	                    $service->delete();
394	                    $deletedCount++;
395	                }
396	            });
397	        }
398	
399	        return [
400	            'synced' => $syncedCount,
401	            'deleted' => $deletedCount,
402	        ];
403	    }
404	
405	    private function resolveCategoryIdFromSquareRow(
406	        string $professionalId,
407	        array $row,
408	        array &$activeCategoryIdByKey,
409	        array &$trashedCategoryByKey,
410	        int &$nextCategorySort
411	    ): ?string {
412	        $categoryName = trim((string) ($row['square_category_name'] ?? ''));
413	        if ($categoryName === '') {
414	            return null;
415	        }
416	
417	        $key = $this->categoryKey($categoryName);
418	        if ($key === '') {
419	            return null;
420	        }
421	
422	        if (isset($activeCategoryIdByKey[$key])) {
423	            return $activeCategoryIdByKey[$key];
424	        }
425	
426	        if (isset($trashedCategoryByKey[$key])) {
427	            /** @var ServiceCategory $category */
428	            $category = $trashedCategoryByKey[$key];
429	            $category->restore();
430	            if ($category->title !== $categoryName) {
431	                $category->title = $categoryName;
432	            }
433	            if ($category->sort_order === null) {
434	                $category->sort_order = $nextCategorySort++;
435	            }
436	            $category->save();
437	
438	            $activeCategoryIdByKey[$key] = $category->id;
439	            unset($trashedCategoryByKey[$key]);
440	
441	            return $category->id;
442	        }
443	
444	        $created = ServiceCategory::query()->create([
445	            'professional_id' => $professionalId,
446	            'title' => $categoryName,
447	            'sort_order' => $nextCategorySort++,
448	        ]);
449	
450	        $activeCategoryIdByKey[$key] = $created->id;
451	
452	        return $created->id;
453	    }
454	
455	    private function categoryKey(string $title): string
456	    {
457	        return mb_strtolower(trim($title));
458	    }
459	
460	    private function existingOrTempId(?string $existingId, string $prefix, string $serviceId): string
461	    {
462	        $trimmed = trim((string) $existingId);
463	        if ($trimmed !== '') {
464	            return $trimmed;
465	        }
466	
467	        $hash = substr(str_replace('-', '', $serviceId), 0, 18);
468	
469	        return sprintf('#commet-%s-%s', $prefix, $hash);
470	    }
471	}
