13	// V2: Bidirectional service sync between Square and Side St. Booking integration — not V2 commerce.
14	class SquareServiceSyncService
15	{
16	    public function __construct(
17	        private readonly SquareApiClient $squareApiClient
18	    ) {}
19	
20	    /**
21	     * Pull services from Square and upsert into Commet.
22	     *
23	     * @return array{synced:int, deleted:int, latest_time:string|null}
24	     */
25	    public function syncFromSquare(Professional $professional, bool $fullSync = false, ?string $beginTimeOverride = null): array
26	    {
27	        $integration = $professional->integrationForProvider(ProfessionalIntegration::PROVIDER_SQUARE);
28	        if (! $integration || empty($integration->access_token) || empty($integration->external_account_id)) {
29	            return ['synced' => 0, 'deleted' => 0, 'latest_time' => null];
30	        }
31	
32	        $beginTime = $beginTimeOverride;
33	        if ($beginTime === null && ! $fullSync && $integration->catalog_latest_time) {
34	            $beginTime = CarbonImmutable::parse($integration->catalog_latest_time)->toIso8601String();
35	        }
36	
37	        try {
38	            $fetched = $this->squareApiClient->fetchAppointmentServiceVariations($professional, $beginTime);
39	            $stats = $this->applySquareSnapshot($professional, $fetched['services'] ?? [], $fullSync);
40	
41	            $integration->catalog_latest_time = isset($fetched['latest_time']) && is_string($fetched['latest_time'])
42	                ? CarbonImmutable::parse($fetched['latest_time'])
43	                : now();
44	            $integration->last_catalog_sync_at = now();
45	            $integration->last_catalog_sync_error = null;
46	            $integration->save();
47	
48	            return [
49	                'synced' => $stats['synced'],
50	                'deleted' => $stats['deleted'],
51	                'latest_time' => $fetched['latest_time'] ?? null,
52	            ];
53	        } catch (\Throwable $e) {
54	            $integration->last_catalog_sync_error = mb_substr($e->getMessage(), 0, 2000);
55	            $integration->last_catalog_sync_at = now();
56	            $integration->save();
57	            throw $e;
58	        }
59	    }
60	
61	    /**
62	     * Push one Commet service mutation to Square.
63	     */
64	    public function pushServiceToSquare(Service $service, string $action = 'upsert'): void
65	    {
66	        $professional = Professional::query()->find($service->professional_id);
67	        if (! $professional) {
68	            return;
69	        }
70	        $integration = $professional->integrationForProvider(ProfessionalIntegration::PROVIDER_SQUARE);
71	        if (! $integration || empty($integration->access_token) || empty($integration->external_account_id)) {
72	            return;
73	        }
74	
75	        // Respect "smart sync" toggle when present.
76	        $smartSyncEnabled = (bool) data_get($professional->site?->settings, 'services_auto_sync_enabled', false);
77	        if (! $smartSyncEnabled) {
78	            return;
79	        }
80	
81	        try {
82	            if ($action === 'delete' || $service->trashed()) {
83	                $itemId = trim((string) ($service->square_catalog_object_id ?? ''));
84	                if ($itemId !== '') {
85	                    try {
86	                        $this->squareApiClient->deleteCatalogObject($professional, $itemId);
87	                    } catch (SquareApiException $e) {
88	                        if ($e->status !== 404) {
89	                            throw $e;
90	                        }
91	                    }
92	                }
93	
94	                Service::withoutEvents(function () use ($service): void {
95	                    Service::query()
96	                        ->withTrashed()
97	                        ->where('id', $service->id)
98	                        ->update([
99	                            'square_last_synced_at' => now(),
100	                            'square_sync_error' => null,
101	                        ]);
102	                });
103	
104	                return;
105	            }
106	
107	            $itemId = $this->existingOrTempId($service->square_catalog_object_id, 'item', $service->id);
108	            $variationId = $this->existingOrTempId($service->square_variation_id, 'var', $service->id);
109	            $itemVersion = $service->square_catalog_version;
110	
111	            $catalogObject = [
112	                'type' => 'ITEM',
113	                'id' => $itemId,
114	                'item_data' => [
115	                    'name' => $service->title,
116	                    'description' => $service->description ?: null,
117	                    'product_type' => 'APPOINTMENTS_SERVICE',
118	                    'variations' => [[
119	                        'type' => 'ITEM_VARIATION',
120	                        'id' => $variationId,
121	                        'item_variation_data' => [
122	                            'item_id' => $itemId,
123	                            'name' => 'Default',
124	                            'pricing_type' => 'FIXED_PRICING',
125	                            'price_money' => [
126	                                'amount' => max(0, (int) ($service->price_cents ?? 0)),
127	                                'currency' => strtoupper((string) ($service->currency_code ?: 'AUD')),
128	                            ],
129	                            'service_duration' => $service->duration_minutes
130	                                ? ((int) $service->duration_minutes * 60 * 1000)
131	                                : null,
132	                            'available_for_booking' => (bool) $service->is_active,
133	                        ],
134	                    ]],
135	                ],
136	            ];
137	
138	            if ($itemVersion !== null && ! str_starts_with($itemId, '#')) {
139	                $catalogObject['version'] = (int) $itemVersion;
140	            }
141	
142	            try {
143	                $upserted = $this->squareApiClient->upsertCatalogObject($professional, $catalogObject);
144	            } catch (SquareApiException $e) {
145	                // If Square has a newer version than we have, retry once with latest version.
146	                if ($e->status !== 400 && $e->status !== 409) {
147	                    throw $e;
148	                }
149	                if (str_starts_with($itemId, '#')) {
150	                    throw $e;
151	                }
152	
153	                $latest = $this->squareApiClient->retrieveCatalogObject($professional, $itemId);
154	                if (! $latest) {
155	                    throw $e;
156	                }
157	
158	                $catalogObject['version'] = isset($latest['version']) ? (int) $latest['version'] : $catalogObject['version'] ?? null;
159	                $latestVariationId = data_get($latest, 'item_data.variations.0.id');
160	                if (is_string($latestVariationId) && $latestVariationId !== '') {
