162	                    $catalogObject['item_data']['variations'][0]['item_variation_data']['item_id'] = $itemId;
163	                }
164	
165	                $upserted = $this->squareApiClient->upsertCatalogObject($professional, $catalogObject);
166	            }
167	
168	            $resolvedItemId = (string) ($upserted['id'] ?? $service->square_catalog_object_id ?? '');
169	            $resolvedVariationId = (string) (data_get($upserted, 'item_data.variations.0.id') ?? $service->square_variation_id ?? '');
170	            $resolvedVersion = isset($upserted['version']) ? (int) $upserted['version'] : $service->square_catalog_version;
171	
172	            Service::withoutEvents(function () use ($service, $resolvedItemId, $resolvedVariationId, $resolvedVersion): void {
173	                Service::query()
174	                    ->withTrashed()
175	                    ->where('id', $service->id)
176	                    ->update([
177	                        'square_catalog_object_id' => $resolvedItemId !== '' ? $resolvedItemId : null,
178	                        'square_variation_id' => $resolvedVariationId !== '' ? $resolvedVariationId : null,
179	                        'square_catalog_version' => $resolvedVersion,
180	                        'square_last_synced_at' => now(),
181	                        'square_sync_error' => null,
182	                    ]);
183	            });
184	        } catch (\Throwable $e) {
185	            Service::withoutEvents(function () use ($service, $e): void {
186	                Service::query()
187	                    ->withTrashed()
188	                    ->where('id', $service->id)
189	                    ->update([
190	                        'square_sync_error' => mb_substr($e->getMessage(), 0, 2000),
191	                    ]);
192	            });
193	
194	            Log::warning('Square push from Commet failed', [
195	                'service_id' => $service->id,
196	                'professional_id' => $service->professional_id,
197	                'message' => $e->getMessage(),
198	            ]);
199	
200	            throw $e;
201	        }
202	    }
